)
func main() {
 f, _ := os.Open(os.Args[1])
 defer f.Close()
 img, _ := jpeg.Decode(f)
 b := img.Bounds()
 // target hex from args 2,3,4 ?
 tr,_:=strconv.ParseInt(os.Args[2],16,32)
 tg,_:=strconv.ParseInt(os.Args[3],16,32)
 tb,_:=strconv.ParseInt(os.Args[4],16,32)
 best:=1<<30
 bx,by:=0,0
 for y:=0;y<b.Dy();y++ {
  for x:=0;x<b.Dx();x++ {
   r,g,bl,_:=img.At(x,y).RGBA()
   r>>=8; g>>=8; bl>>=8
   d:= (int(r)-int(tr))*(int(r)-int(tr)) + (int(g)-int(tg))*(int(g)-int(tg)) + (int(bl)-int(tb))*(int(bl)-int(tb))
   if d<best {best=d; bx=x; by=y}
  }
 }
 fmt.Printf("best %d,%d diff %d\n", bx,by,best)
 // also print neighborhood around best
 for y:=by-2; y<=by+2; y++ {
  if y<0||y>=b.Dy() {continue}
  for x:=bx-2; x<=bx+2; x++ {
   if x<0||x>=b.Dx() {continue}
   r,g,bl,_:=img.At(x,y).RGBA()
   fmt.Printf("(%d,%d)#%02x%02x%02x ", x,y, r>>8,g>>8,bl>>8)
  }
  fmt.Println()
 }
 // also print top-left 5x5
 fmt.Println("top-left:")
 for y:=0;y<5;y++{
  for x:=0;x<5;x++{
   r,g,bl,_:=img.At(x,y).RGBA()
   fmt.Printf("(%d,%d)#%02x%02x%02x ", x,y, r>>8,g>>8,bl>>8)
  }
  fmt.Println()
 }
 // print region for 5x3 cell (0,0) average? cell size 64x80
 fmt.Println("averages:")
 outW,outH:=5,3
 for oy:=0;oy<outH;oy++{
  for ox:=0;ox<outW;ox++{
   x0:=ox*b.Dx()/outW
   x1:=(ox+1)*b.Dx()/outW
   y0:=oy*b.Dy()/outH
   y1:=(oy+1)*b.Dy()/outH
   var sr,sg,sb, cnt int
   for y:=y0;y<y1;y++{
    for x:=x0;x<x1;x++{
     r,g,bl,_:=img.At(x,y).RGBA()
     sr+=int(r>>8); sg+=int(g>>8); sb+=int(bl>>8); cnt++
    }
   }
   fmt.Printf("cell %d,%d avg #%02x%02x%02x\n", ox,oy, sr/cnt, sg/cnt, sb/cnt)
  }
 }
}
