import subprocess, os, re

def get_colors(img, w, h):
    env={k:v for k,v in os.environ.items() if k not in ["TERM","COLUMNS","LINES"]}
    r=subprocess.run(["./executable", f"--size={w}x{h}", "--html", "--colors", img], capture_output=True, env=env)
    html=r.stdout.decode()
    colors=re.findall(r"color:#([0-9a-fA-F]{6})", html)
    return colors

c11=get_colors("assets/grind.jpg", 320, 240)
c53=get_colors("assets/grind.jpg", 5, 3)
print(c53)

def hex_to_rgb(h):
    return (int(h[0:2],16), int(h[2:4],16), int(h[4:6],16))

# for each 5x3 cell, find best matching pixel in 1:1 image (full search)
for idx53, target_hex in enumerate(c53):
    ox=idx53%5
    oy=idx53//5
    tr,tg,tb=hex_to_rgb(target_hex)
    best=None
    bestpos=None
    for y in range(240):
        for x in range(320):
            idx=y*320+x
            r,g,b=hex_to_rgb(c11[idx])
            d=(r-tr)**2+(g-tg)**2+(b-tb)**2
            if best is None or d<best:
                best=d
                bestpos=(x,y)
                besthex=c11[idx]
                if d==0:
                    break
        if best==0:
            break
    print(f"cell {ox},{oy} target {target_hex} best {besthex} at {bestpos} diff {best}")
PY
