#include <string.h>
extern void* jpeg_std_error(void* err);
extern void jpeg_CreateDecompress(void* cinfo, int version, size_t structsize);
extern void jpeg_stdio_src(void* cinfo, FILE* infile);
extern int jpeg_read_header(void* cinfo, int require_image);
extern void jpeg_start_decompress(void* cinfo);
extern unsigned int jpeg_read_scanlines(void* cinfo, unsigned char** scanlines, unsigned int max_lines);
extern void jpeg_finish_decompress(void* cinfo);
extern void jpeg_destroy_decompress(void* cinfo);
int main(int argc, char**argv) {
    const char* filename = argv[1];
    const char* outname = argv[2];
    void* err_buf = malloc(512);
    void* cinfo_buf = malloc(656);
    memset(err_buf, 0, 512);
    memset(cinfo_buf, 0, 656);
    jpeg_std_error(err_buf);
    *(void**)cinfo_buf = err_buf;
    jpeg_CreateDecompress(cinfo_buf, 80, 656);
    FILE* f = fopen(filename, "rb");
    jpeg_stdio_src(cinfo_buf, f);
    jpeg_read_header(cinfo_buf, 1);
    jpeg_start_decompress(cinfo_buf);
    int out_w = *(int*)((char*)cinfo_buf+136);
    int out_h = *(int*)((char*)cinfo_buf+140);
    int comp = *(int*)((char*)cinfo_buf+148);
    fprintf(stderr,"w=%d h=%d comp=%d\n", out_w,out_h,comp);
    FILE* out = fopen(outname,"wb");
    // write header: w h comp as binary ints?
    fwrite(&out_w,4,1,out);
    fwrite(&out_h,4,1,out);
    fwrite(&comp,4,1,out);
    unsigned char* row = malloc(out_w*comp);
    unsigned char* rows[1]={row};
    for(int y=0;y<out_h;y++){
        jpeg_read_scanlines(cinfo_buf, rows, 1);
        fwrite(row,1,out_w*comp,out);
    }
    jpeg_finish_decompress(cinfo_buf);
    jpeg_destroy_decompress(cinfo_buf);
    fclose(f); fclose(out);
    return 0;
}
